```sparql
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate
WHERE {
  VALUES ?film { dbr:The_Appeal_to_Conscience dbr:Pretty_Persuasion }

  # film label (optional)
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER (lang(?filmLabel) = "en") }

  # director – prefer dbp:director, fall back to dbo:director
  OPTIONAL { ?film dbp:director ?director . }
  OPTIONAL {
    ?film dbo:director ?dir2 .
    FILTER (!BOUND(?director))
    BIND(?dir2 AS ?director)
  }

  # director label (optional)
  OPTIONAL {
    ?director rdfs:label ?directorLabel FILTER (lang(?directorLabel) = "en")
  }

  # director birth date – prefer dbp:birthDate, fall back to dbo:birthDate
  OPTIONAL { ?director dbp:birthDate ?birthDate . }
  OPTIONAL {
    ?director dbo:birthDate ?bd2 .
    FILTER (!BOUND(?birthDate))
    BIND(?bd2 AS ?birthDate)
  }
}
LIMIT 100
